     PrefabUtility.UnpackPrefabInstance(visual,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);visual.name="Synty City Skin "+id;foreach(var t in visual.GetComponentsInChildren<Transform>(true).OrderByDescending(t=>Depth(t)).ToArray()){if(!t||t==visual.transform||t.gameObject.activeInHierarchy)continue;if(t.GetComponentsInChildren<Renderer>(true).Length>0){UnityEngine.Object.DestroyImmediate(t.gameObject);removed++;}}
     foreach(var t in visual.GetComponentsInChildren<Transform>(true))GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);foreach(var m in visual.GetComponentsInChildren<MonoBehaviour>(true))if(m)UnityEngine.Object.DestroyImmediate(m);foreach(var c in visual.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);
     var animator=visual.GetComponentInChildren<Animator>();if(!animator||!animator.avatar||!animator.avatar.isValid||!animator.avatar.isHuman)throw new InvalidOperationException("Preset does not have a valid Humanoid avatar: "+id);animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.CullUpdateTransforms;
     foreach(var renderer in visual.GetComponentsInChildren<SkinnedMeshRenderer>()){var materials=renderer.sharedMaterials;for(int i=0;i<materials.Length;i++){var old=materials[i];if(!old)continue;if(!converted.TryGetValue(old,out Material mat)){mat=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Synty URP "+old.name};string palettePath="Assets/CityExpansion/SyntyNpcPaletteTextures/"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(old))+".png";var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(palettePath);if(!tex)throw new InvalidOperationException("Baked Synty palette missing: "+old.name);mat.SetTexture("_BaseMap",tex);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Smoothness",.18f);mat.enableInstancing=true;AssetDatabase.CreateAsset(mat,AssetDatabase.GenerateUniqueAssetPath(folder+"/"+mat.name.Replace(" ","_")+".mat"));converted.Add(old,mat);}materials[i]=mat;}renderer.sharedMaterials=materials;renderer.updateWhenOffscreen=false;renderers++;}
     var b=BoundsOf(visual);visual.transform.localScale*=1.75f/b.size.y;b=BoundsOf(visual);visual.transform.position+=new Vector3(-b.center.x,-b.min.y,-b.center.z);
     if(prefabs.Count==0){if(AnimationMode.InAnimationMode())throw new InvalidOperationException("Close animation preview before running NPC rig test.");AnimationMode.StartAnimationMode();try{AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(animator.gameObject,walk,walk.length*.15f);AnimationMode.EndSampling();var leg=animator.GetBoneTransform(HumanBodyBones.LeftUpperLeg);if(!leg)throw new InvalidOperationException("Humanoid left leg missing.");var first=leg.localRotation;AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(animator.gameObject,walk,walk.length*.65f);AnimationMode.EndSampling();walkMotion=Quaternion.Angle(first,leg.localRotation);if(walkMotion<.5f)throw new InvalidOperationException("Walking clip did not animate Synty leg; population was not installed.");}finally{AnimationMode.StopAnimationMode();}}
     var skin=PrefabUtility.SaveAsPrefabAsset(visual,folder+"/Skin-"+id+".prefab");prefabs.Add(skin);appearances.Add(BakeAppearance(visual,animator,walk,skin,id,folder));
    }
    finally{UnityEngine.Object.DestroyImmediate(visual);}
   }
   var roadBounds=BoundsOf(roads.gameObject);roadBounds.Expand(new Vector3(6,18,6));var markups=new List<NavMeshBuildMarkup>{new NavMeshBuildMarkup{root=roads,overrideArea=true,area=0}};var sources=new List<NavMeshBuildSource>();NavMeshBuilder.CollectSources(roadBounds,~0,NavMeshCollectGeometry.PhysicsColliders,1,markups,sources);sources.RemoveAll(s=>s.shape==NavMeshBuildSourceShape.Terrain);if(sources.Count==0)throw new InvalidOperationException("No navigation geometry found.");var settings=NavMesh.GetSettingsByIndex(0);settings.agentRadius=.30f;settings.agentHeight=1.8f;settings.agentClimb=.3f;settings.overrideVoxelSize=true;settings.voxelSize=.10f;var data=NavMeshBuilder.BuildNavMeshData(settings,sources,roadBounds,Vector3.zero,Quaternion.identity);if(!data)throw new InvalidOperationException("City navigation bake failed.");data.name="Walking City Roads";AssetDatabase.CreateAsset(data,folder+"/CityRoadNavigation.asset");var temporary=NavMesh.AddNavMeshData(data);
   try
   {
    var nodes=new List<Vector3>();foreach(var filter in roads.GetComponentsInChildren<MeshFilter>()){if(filter.name=="Central Market Square")continue;var v=filter.sharedMesh.vertices;for(int i=0;i+1<v.Length;i+=12){var p=filter.transform.TransformPoint((v[i]+v[i+1])*.5f);if(NavMesh.SamplePosition(p,out NavMeshHit hit,1.5f,1)&&nodes.All(n=>Vector3.Distance(n,hit.position)>4))nodes.Add(hit.position);}}
    if(nodes.Count<16)throw new InvalidOperationException("Fewer than 16 usable road positions; NPC population not installed.");var components=new List<List<Vector3>>();var unused=new HashSet<Vector3>(nodes);while(unused.Count>0){var seed=unused.First();var set=new List<Vector3>();foreach(var point in unused.ToArray()){var path=new NavMeshPath();if(NavMesh.CalculatePath(seed,point,1,path)&&path.status==NavMeshPathStatus.PathComplete){set.Add(point);unused.Remove(point);}}if(set.Count==0){unused.Remove(seed);continue;}components.Add(set);}var connected=components.OrderByDescending(c=>c.Count).First();if(connected.Count<16)throw new InvalidOperationException("Road network cannot support 16 connected spawn sites.");
    var routes=new List<CityCrowdRoute>();for(int from=0;from<connected.Count;from++){var neighbors=Enumerable.Range(0,connected.Count).Where(i=>i!=from).OrderBy(i=>Vector3.Distance(connected[from],connected[i])).Take(5);foreach(int to in neighbors){var path=new NavMeshPath();if(!NavMesh.CalculatePath(connected[from],connected[to],1,path)||path.status!=NavMeshPathStatus.PathComplete||path.corners.Length<2)continue;float length=0;for(int k=1;k<path.corners.Length;k++)length+=Vector3.Distance(path.corners[k-1],path.corners[k]);if(length<2)continue;routes.Add(new CityCrowdRoute{From=from,To=to,Corners=path.corners,Length=length});}}
    if(routes.Count<10)throw new InvalidOperationException("Insufficient connected walking routes for crowd.");var root=new GameObject("Synty Walking City Population 1500");Undo.RegisterCreatedObjectUndo(root,"Add 1500-person Synty crowd");var registry=root.AddComponent<CityPopulationNavigation>();registry.Data=data;var crowd=root.AddComponent<CityCrowdManager>();crowd.Routes=routes.ToArray();crowd.Appearances=appearances.ToArray();crowd.People=new CityCrowdPerson[1500];crowd.DetailedPerAppearance=12;crowd.DetailDistance=45;crowd.DrawDistance=220;var random=new System.Random(17421);for(int i=0;i<crowd.People.Length;i++){var person=new CityCrowdPerson{Route=random.Next(routes.Count),Skin=i%appearances.Count,Speed=1.05f+(float)random.NextDouble()*.5f,Lane=((float)random.NextDouble()-.5f)*.7f};person.Distance=(float)random.NextDouble()*routes[person.Route].Length;CityCrowdManager.Locate(routes[person.Route],person.Distance,person.Lane,out person.Position,out person.Yaw);crowd.People[i]=person;}
    var preview=new GameObject("24 NPC Scene Previews - Hidden During Play");preview.transform.SetParent(root.transform,false);crowd.EditorPreview=preview;for(int i=0;i<24;i++){var person=crowd.People[i*61];var visual=new GameObject("City NPC Preview "+(i+1).ToString("00"));visual.transform.SetParent(preview.transform,false);visual.transform.SetPositionAndRotation(person.Position,Quaternion.Euler(0,person.Yaw,0));var appearance=appearances[person.Skin];for(int part=0;part<appearance.PoseA.Length;part++){var piece=new GameObject("Baked Walking Pose "+part);piece.transform.SetParent(visual.transform,false);piece.AddComponent<MeshFilter>().sharedMesh=appearance.PoseA[part];piece.AddComponent<MeshRenderer>().sharedMaterial=appearance.Materials[part];}}
    var oldPopulation=GameObject.Find("Synty Walking City Population");if(oldPopulation){Undo.RecordObject(oldPopulation,"Replace old 16 NPC setup");oldPopulation.SetActive(false);}
    for(int i=0;i<original.Length;i++)if(original[i].localToWorldMatrix!=matrices[i])throw new InvalidOperationException("Existing model moved; population rolled back.");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Scene save failed.");Directory.CreateDirectory("Logs");File.WriteAllText("Logs/TestSyntyCityPopulation1500-report.txt","Installed a 1500-person city crowd using only six optimized Synty skins. All Humanoid avatars validated; walking sample leg movement "+walkMotion.ToString("F2")+" degrees. Removed "+removed+" inactive modular objects; retained "+renderers+" skinned renderers across six base skins. Navigation bake validated "+connected.Count+" connected road nodes and "+routes.Count+" cached walking routes. 1500 individual crowd records simulate walking and idle pauses. At most 72 nearby actors are fully animated; distant characters use instanced two-pose walking meshes within 220m view distance. Added 24 visible Scene previews, automatically hidden in Play. Runtime crowd movement still requires Play-mode observation. No other character packs used; existing town and castle models preserved.\nBackup: "+backup);Debug.Log("Synty rig test passed; 1500-person crowd installed in Lower Castle City. Enter Play to see crowd; 24 preview characters visible in Scene.");
   }
   finally{if(temporary.valid)temporary.Remove();}
