  internal static CityCrowdAppearance BakeAppearance(GameObject visual,Animator animator,AnimationClip walk,GameObject skin,int id,string folder)
  {
   var result=new CityCrowdAppearance{Skin=skin};Material[] materials=null;for(int phase=0;phase<2;phase++){AnimationMode.StartAnimationMode();try{AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(animator.gameObject,walk,walk.length*(phase==0?.15f:.65f));AnimationMode.EndSampling();var groups=new Dictionary<Material,List<CombineInstance>>();var bakedMeshes=new List<Mesh>();try{foreach(var r in visual.GetComponentsInChildren<SkinnedMeshRenderer>()){var baked=new Mesh();r.BakeMesh(baked);bakedMeshes.Add(baked);for(int sub=0;sub<baked.subMeshCount;sub++){var mat=r.sharedMaterials[Mathf.Min(sub,r.sharedMaterials.Length-1)];if(!groups.TryGetValue(mat,out var list)){list=new List<CombineInstance>();groups.Add(mat,list);}list.Add(new CombineInstance{mesh=baked,subMeshIndex=sub,transform=r.localToWorldMatrix});}}if(materials==null)materials=groups.Keys.ToArray();var meshes=new Mesh[materials.Length];for(int part=0;part<materials.Length;part++){var mesh=new Mesh{name="Synty Far Walking "+id+" "+phase+" "+part,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.CombineMeshes(groups[materials[part]].ToArray(),true,true);mesh.RecalculateBounds();meshes[part]=mesh;}var common=meshes[0].bounds;foreach(var mesh in meshes)common.Encapsulate(mesh.bounds);var offset=new Vector3(common.center.x,common.min.y,common.center.z);for(int part=0;part<meshes.Length;part++){var mesh=meshes[part];var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++)vertices[i]-=offset;mesh.vertices=vertices;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/Far-"+id+"-"+phase+"-"+part+".asset");}if(phase==0)result.PoseA=meshes;else result.PoseB=meshes;}finally{foreach(var mesh in bakedMeshes)UnityEngine.Object.DestroyImmediate(mesh);}}finally{AnimationMode.StopAnimationMode();}}result.Materials=materials;return result;
  }
  static int Depth(Transform t){int n=0;while(t.parent){n++;t=t.parent;}return n;}
  static AnimationClip Clip(string path){var clip=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().FirstOrDefault(c=>!c.name.StartsWith("__preview__"));if(!clip)throw new InvalidOperationException("Animation missing: "+path);return clip;}
  static Bounds BoundsOf(GameObject go){var r=go.GetComponentsInChildren<Renderer>();if(r.Length==0)throw new InvalidOperationException("No active character geometry.");var b=r[0].bounds;foreach(var part in r)b.Encapsulate(part.bounds);return b;}
 }
